#include "AudioMixer.h"
#include <algorithm>
namespace NeoEngine {bool AudioMixer::Play(uint32_t id,std::vector<int16_t>s,uint16_t g){if(s.empty()||s.size()>kMaxSamplesPerVoice)return false;for(const auto&v:m_Voices)if(v.id==id)return false;if(m_Voices.size()==kMaxVoices)return false;m_Voices.push_back({id,std::move(s),0,g});return true;}bool AudioMixer::Stop(uint32_t id){auto it=std::find_if(m_Voices.begin(),m_Voices.end(),[&](const auto&v){return v.id==id;});if(it==m_Voices.end())return false;m_Voices.erase(it);return true;}void AudioMixer::Mix(size_t frames,std::vector<int16_t>&out){out.assign(frames*2,0);for(size_t f=0;f<frames;++f){int64_t sum=0;for(auto&v:m_Voices)if(v.cursor<v.samples.size())sum+=static_cast<int64_t>(v.samples[v.cursor++])*v.gain/256;sum=std::clamp<int64_t>(sum,-32768,32767);out[f*2]=out[f*2+1]=static_cast<int16_t>(sum);}m_Voices.erase(std::remove_if(m_Voices.begin(),m_Voices.end(),[](const auto&v){return v.cursor==v.samples.size();}),m_Voices.end());}}
